<section class="auth-wrap"><div class="auth-card"><div class="eyebrow">START SOMETHING GOOD</div><h1>Make room for <em>ideas.</em></h1><p>Create your PrintPack account.</p><form method="post" action="<?= e(url('register')) ?>" class="form-stack"><?= csrf_field() ?><label>Full name<input class="form-control" name="name" required maxlength="120" autocomplete="name" placeholder="Your full name"></label><label>Email address<input class="form-control" type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label><label>Password<input class="form-control" type="password" name="password" required minlength="8" autocomplete="new-password" placeholder="At least 8 characters"></label><label>I'm joining as<select class="form-select" name="role"><option value="customer">Customer — order products</option><option value="vendor">Vendor — sell printing services</option></select></label><button class="btn btn-green w-100">Create account ↗</button></form><p class="auth-bottom">Already have an account? <a href="<?= e(url('login')) ?>">Sign in</a></p></div></section>
